\begin{algorithm}
\algname{Algorithm}
\caption{$\Query(i)$}
\begin{algorithmic}
\State $(k_0, k_1) \gets \Gen(1^\secpar, i, 1)$
\Return $(q_0, q_1) \gets (k_0, k_1)$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\algname{Algorithm}
\caption{$\Answer(b, q_b, D)$}
\begin{algorithmic}
\State $a_b \gets \sum_{j \in [N]} D[j] \cdot \Eval(b, q_b, j)$
\Comment{sum in the DPF range group}
\Return $a_b$
\end{algorithmic}
\end{algorithm}

\begin{algorithm}
\algname{Algorithm}
\caption{$\Recon(i, a_0, a_1)$}
\begin{algorithmic}
\Return $D[i] \gets a_0 + a_1$
\end{algorithmic}
\end{algorithm}
